import{_ as s,C as n,c as i,o as r,a3 as e,G as a}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Fiscal positions","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/taxes/fiscal-positions.md","filePath":"master/finance/taxes/fiscal-positions.md","lastUpdated":1793074831000}'),l={name:"master/finance/taxes/fiscal-positions.md"};function c(u,o,p,h,m,d){const t=n("ImagePopup");return r(),i("div",null,[o[0]||(o[0]=e('<h1 id="fiscal-positions" tabindex="-1">Fiscal positions <a class="header-anchor" href="#fiscal-positions" aria-label="Permalink to &quot;Fiscal positions&quot;">​</a></h1><p>A fiscal position is a set of rules for a type of customer or a region. Customers in another country, or businesses that are tax exempt, may need different accounts or different taxes than your usual customers. You describe those rules once and attach the position to a customer or a document.</p><blockquote><p><strong>In simple words:</strong> A fiscal position says: for this kind of customer, swap these accounts and these taxes.</p></blockquote><p>This screen exists only in the <strong>Accounting</strong> app.</p><h2 id="when-to-use-this-page" tabindex="-1">When to use this page <a class="header-anchor" href="#when-to-use-this-page" aria-label="Permalink to &quot;When to use this page&quot;">​</a></h2><ul><li>You sell to customers in another country.</li><li>You need a different income account for exports.</li><li>You want to record that a customer follows a special tax rule.</li></ul><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><p><code>Accounting → Configurations → Accounting → Fiscal Positions</code></p>',8)),a(t,{src:"/images1/finance/fiscal_positions_list.png",alt:"Fiscal Positions list with the Export Customers position"}),o[1]||(o[1]=e('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows <strong>Name</strong>, <strong>Company</strong>, <strong>Country</strong>, <strong>Country Group</strong>, <strong>Created By</strong>, <strong>Zip From</strong>, <strong>Zip To</strong> and <strong>Detect Automatically</strong>. A new database has no fiscal positions.</p><h2 id="create-a-fiscal-position" tabindex="-1">Create a fiscal position <a class="header-anchor" href="#create-a-fiscal-position" aria-label="Permalink to &quot;Create a fiscal position&quot;">​</a></h2><ol><li>Go to the Fiscal Positions page.</li><li>Click <strong>New Fiscal Position</strong>.</li><li>Fill in the fields below.</li><li>Click <strong>Create</strong>.</li></ol>',4)),a(t,{src:"/images1/finance/fiscal_position_form.png",alt:"New Fiscal Position form with Name Export Customers, Country Germany, Company My Company, and one Account Mapping row"}),o[2]||(o[2]=e('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> A name you will recognise, such as <code>Export Customers</code>. Required.</li><li><strong><em>Foreign VAT:</em></strong> The tax number to use for this position. Required.</li><li><strong><em>Country:</em></strong> The country the position is meant for.</li><li><strong><em>Country Group:</em></strong> A group of countries, instead of a single country.</li><li><strong><em>Zip From</em> and <em>Zip To:</em></strong> A range of postal codes the position covers. Both are required.</li><li><strong><em>Company:</em></strong> The company that owns the position. Required. Mappings can only use taxes and accounts of this company.</li><li><strong><em>Detect Automatically:</em></strong> Mark the position as one that fits customers by their country or postal code.</li><li><strong><em>Notes:</em></strong> Free text for your team.</li></ul><h3 id="tax-mapping-tab" tabindex="-1">Tax Mapping tab <a class="header-anchor" href="#tax-mapping-tab" aria-label="Permalink to &quot;Tax Mapping tab&quot;">​</a></h3><p>Click <strong>Add Tax Mapping</strong> and fill in:</p><ul><li><strong><em>Tax Source:</em></strong> The tax you normally use. Required.</li><li><strong><em>Tax Destination:</em></strong> The tax to use instead. Leave it empty to mean &quot;no tax&quot;.</li></ul><h3 id="account-mapping-tab" tabindex="-1">Account Mapping tab <a class="header-anchor" href="#account-mapping-tab" aria-label="Permalink to &quot;Account Mapping tab&quot;">​</a></h3><p>Click <strong>Add Account Mapping</strong> and fill in:</p><ul><li><strong><em>Source Account:</em></strong> The account Aureus would normally use. Required.</li><li><strong><em>Destination Account:</em></strong> The account to use instead. Required.</li></ul><h2 id="where-a-fiscal-position-is-used" tabindex="-1">Where a fiscal position is used <a class="header-anchor" href="#where-a-fiscal-position-is-used" aria-label="Permalink to &quot;Where a fiscal position is used&quot;">​</a></h2><ul><li>On a customer, in the <strong>Sales &amp; Purchases</strong> tab, <strong>Fiscal Position</strong>. See <a href="./../../sales/sales/quotations-orders/manage-customers.html">Customers</a>.</li><li>On an invoice or bill, in <strong>Other Information</strong>, under <strong>Accounting</strong>, <strong>Fiscal Position</strong>. The field hint says: &quot;Fiscal positions are used to adapt taxes and accounts based on the customer location.&quot; You cannot change it after the document is posted.</li><li>On a journal entry, in <strong>Other Information</strong>.</li></ul><p>When Aureus builds the lines of a document that has a fiscal position, it swaps accounts using the <strong>Account Mapping</strong>. This works for the receivable and payable accounts and for the income and expense accounts of products.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The taxes on a line come from the <strong>Taxes</strong> field of the line. After you choose a fiscal position, check the <strong>Taxes</strong> column and change a tax by hand if needed.</p></div><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Create <code>Export Customers</code>, <strong>Country</strong> <code>Germany</code>. In <strong>Account Mapping</strong>, set <strong>Source Account</strong> <code>Product Sales</code> and <strong>Destination Account</strong> <code>Export Sales</code>. Choose this position on a customer from Germany. Invoices for that customer book their product income to <code>Export Sales</code>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./taxes.html">Taxes</a></li><li><a href="./../get-started/chart-of-accounts.html">Chart of accounts</a></li><li><a href="./../../sales/sales/quotations-orders/manage-customers.html">Customers</a></li><li><a href="./../customer-invoices/create-invoice.html">Create an invoice</a></li></ul>',16))])}const x=s(l,[["render",c]]);export{f as __pageData,x as default};
